$ErrorActionPreference='Stop'
$python='C:\inetpub\wwwroot\Zhumadian\Application\runtime\python\python.exe'
$text= & $python -I -B -c "import base64,zlib;exec(zlib.decompress(base64.b64decode('')))" apply
if($LASTEXITCODE -ne 0){throw 'R34_RETENTION_REFUSED_NO_UNVERIFIED_DELETE'}
$value=$text|ConvertFrom-Json
if($value.activeRelease -ne 'R34' -or -not $value.passed){throw 'R34_RETENTION_RESULT_REFUSED'}
$json=$value|ConvertTo-Json -Depth 6 -Compress
Set-Clipboard -Value $json
Write-Output $json
